import math
import random
import numpy as np

def deterministic_meanfield(beta, start, steps):
    path = [float(start)]
    for _ in range(steps):
        path.append(math.tanh(beta * path[-1]))
    return path

def solve(beta, start, steps):
    return deterministic_meanfield(beta, start, steps)

p13-cascade-rounds:
import math
import random
import numpy as np

def threshold_cascade(n, edges, thresholds, seeds):
    """Synchronous failed-neighbor count rule; rounds[0] is direct damage."""
    neighbors = [set() for _ in range(n)]
    for a, b in edges:
        neighbors[a].add(b)
        neighbors[b].add(a)
    failed = set(seeds)
    rounds = [sorted(failed)]
    while True:
        added = [i for i in range(n) if i not in failed
                 and sum(j in failed for j in neighbors[i]) >= thresholds[i]]
        if not added:
            return rounds
        failed.update(added)
        rounds.append(sorted(added))

def solve(n, edges, thresholds, seeds):
    return threshold_cascade(n, edges, thresholds, seeds)

p13-largest-survivor:
import math
import random
import numpy as np

def largest_survivor_fraction(n, edges, failed):
    """Largest connected surviving component divided by the original n."""
    alive = set(range(n)) - set(failed)
    neighbors = {i: set() for i in alive}
    for a, b in edges:
        if a in alive and b in alive:
            neighbors[a].add(b)
            neighbors[b].add(a)
    largest = 0
    while alive:
        start = alive.pop()
        seen = {start}
        frontier = [start]
        while frontier:
            for node in neighbors[frontier.pop()]:
                if node in alive:
                    alive.remove(node)
                    seen.add(node)
                    frontier.append(node)
        largest = max(largest, len(seen))
    return largest / n

def solve(n, edges, failed):
    return largest_survivor_fraction(n, edges, failed)

p13-recovery-trajectory:
import math
import random
import numpy as np

def recovery_path(rate, boundary, initial, dt, steps):
    """Euler path for dx/dt=-rate*x*(1-x/boundary), positive initial only."""
    values = [float(initial)]
    for _ in range(steps):
        current = values[-1]
        values.append(current - dt * rate * current * (1 - current / boundary))
    return values

def solve(rate, boundary, initial, dt, steps):
    return recovery_path(rate, boundary, initial, dt, steps)

